(function(){'use strict';if(document.body?.dataset.page!=='personalization')return;const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function csv(v){return String(v||'').split(',').map(x=>x.trim()).filter(Boolean)}
function hydrate(){const s=window.NEXZOPersonalization?.snapshot?.();if(!s)return;const p=s.profile||{};$('nxCourse').value=p.course||'';$('nxBranch').value=p.branch||'';$('nxSemester').value=p.semester||'';$('nxDailyMinutes').value=p.dailyMinutes||60;$('nxSubjects').value=(p.subjects||[]).join(', ');$('nxBacklogs').value=(p.backlogs||[]).join(', ');$('nxExamDates').value=Object.entries(p.examDates||{}).map(([k,v])=>`${k}=${v}`).join(', ');$('nxCareerGoal').value=p.careerGoal||'';$('nxLanguage').value=p.language||'Hinglish';$('nxStyle').value=p.explanationStyle||'Concise + examples';const c=s.checkins?.[new Date().toLocaleDateString('en-CA')];if(c){$('nxAvailable').value=c.availableMinutes||60;$('nxEnergy').value=c.energy||'Normal';$('nxWorkload').value=c.workload||'Normal';$('nxFocus').value=c.focus||'Adaptive';$('nxCheckinNote').value=c.note||''}render(s)}
function render(s){const mastery=Object.values(s.mastery||{}).sort((a,b)=>a.score-b.score);$('nxMastery').innerHTML=mastery.length?mastery.slice(0,12).map(m=>`<div class="nx-mastery-row"><div class="nx-mastery-head"><div><b>${esc(m.topic)}</b><small> · ${esc(m.subject)}</small></div><span class="nx-tag">${m.assessed?`${m.score}%`:''} ${esc(m.status)}</span></div><div class="nx-meter"><i style="width:${m.score}%"></i></div><small>${m.attempts||0} tracked activities · ${m.mistakeCount||0} mistakes</small></div>`).join(''):'<div class="nx-empty">Add subjects or complete Planner work to start mastery tracking.</div>';const rec=s.recommendations||[];$('nxRecommendations').innerHTML=rec.length?rec.slice(0,6).map(r=>`<div class="nx-rec-row"><div class="nx-rec-head"><div><b>${esc(r.topic)}</b><small> · ${esc(r.subject)}</small></div><span class="nx-tag">${r.durationMinutes} min</span></div><p>${esc(r.action)}</p><ul class="nx-why">${(r.why||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="nx-pactions"><button class="nx-pbtn secondary" data-feedback="${esc(r.id)}:useful">Useful</button><button class="nx-pbtn secondary" data-feedback="${esc(r.id)}:too-hard">Too hard</button><button class="nx-pbtn secondary" data-feedback="${esc(r.id)}:too-easy">Too easy</button><button class="nx-pbtn secondary" data-feedback="${esc(r.id)}:not-relevant">Not relevant</button><button class="nx-pbtn secondary" data-feedback="${esc(r.id)}:already-know">Already know</button><button class="nx-pbtn" data-study-recommendation="${esc(r.id)}">Study with NEXZO</button><button class="nx-pbtn" data-add-planner="${esc(r.id)}">Add to Planner</button></div></div>`).join(''):'<div class="nx-empty">Complete your profile to generate recommendations.</div>';const mistakes=Object.values(s.mistakes||{}).sort((a,b)=>(b.count||0)-(a.count||0));$('nxMistakes').innerHTML=mistakes.length?mistakes.slice(0,10).map(m=>`<div class="nx-memory-row"><b>${esc(m.concept)}</b><small>${esc(m.subject)} · ${esc(m.topic)} · repeated ${m.count}×</small></div>`).join(''):'<div class="nx-empty">No repeated mistake pattern detected yet.</div>';$('nxMemory').innerHTML=`<div class="nx-memory-row"><b>Academic profile</b><small>${esc((s.profile.subjects||[]).join(', ')||'No subjects yet')}</small></div><div class="nx-memory-row"><b>Current goal</b><small>${esc(s.profile.careerGoal||'Not set')}</small></div><div class="nx-memory-row"><b>Teaching style</b><small>${esc(s.profile.language)} · ${esc(s.profile.explanationStyle)}</small></div><div class="nx-memory-row"><b>Learning history</b><small>${s.events?.length||0} structured events · ${Object.keys(s.mistakes||{}).length} mistake patterns</small></div>`;document.querySelectorAll('[data-feedback]').forEach(b=>b.onclick=()=>{const [id,value]=b.dataset.feedback.split(':');window.NEXZOPersonalization.feedback(id,value);window.NEXZOShell?.toast?.('Recommendation feedback saved.','success')});document.querySelectorAll('[data-study-recommendation]').forEach(b=>b.onclick=()=>{const r=(window.NEXZOPersonalization.snapshot().recommendations||[]).find(x=>x.id===b.dataset.studyRecommendation);if(!r)return;localStorage.setItem('nexzo.ai.launch',JSON.stringify({mode:'explain',prompt:`Help me study ${r.topic} in ${r.subject}. Goal: ${r.action}. I have ${r.durationMinutes} minutes. Start at my current mastery level (${r.mastery}%) and use my saved learning context.`,recommendationId:r.id,at:Date.now()}));location.href='ai-assistant.html'});document.querySelectorAll('[data-add-planner]').forEach(b=>b.onclick=()=>{const r=(window.NEXZOPersonalization.snapshot().recommendations||[]).find(x=>x.id===b.dataset.addPlanner);if(!r)return;const store=window.NEXZOTaskStore;if(store?.upsert){store.upsert({id:`personalized_${String(r.id).replace(/[^a-z0-9_-]/gi,'_')}`,title:`${r.topic} — ${r.action}`,subject:r.subject,type:'Personalized Study',taskType:'Personalized Study',difficulty:r.mastery<35?'Beginner':r.mastery<65?'Intermediate':'Advanced',priority:r.priority>=90?'High':'Medium',plannedMinutes:r.durationMinutes,hours:`${r.durationMinutes} Minutes daily`,duration:'1 Day',status:'pending',completed:false,source:'personalization',recommendationId:r.id,createdAtMs:Date.now(),updatedAtMs:Date.now()},{cloud:true,immediate:true});window.NEXZOShell?.toast?.('Personalized task added to Planner.','success')}else{window.NEXZOShell?.toast?.('Planner is still loading. Try again in a moment.','error')}})}
function bind(){$('nxProfileForm').onsubmit=e=>{e.preventDefault();window.NEXZOPersonalization.updateProfile({course:$('nxCourse').value,branch:$('nxBranch').value,semester:$('nxSemester').value,dailyMinutes:Number($('nxDailyMinutes').value)||60,subjects:csv($('nxSubjects').value),backlogs:csv($('nxBacklogs').value),examDates:Object.fromEntries(csv($('nxExamDates').value).map(x=>x.split('=').map(y=>y.trim())).filter(x=>x.length===2&&x[0]&&x[1])),careerGoal:$('nxCareerGoal').value,language:$('nxLanguage').value,explanationStyle:$('nxStyle').value});window.NEXZOShell?.toast?.('Learning profile saved.','success');hydrate()};$('nxCheckinForm').onsubmit=e=>{e.preventDefault();window.NEXZOPersonalization.dailyCheckin({availableMinutes:$('nxAvailable').value,energy:$('nxEnergy').value,workload:$('nxWorkload').value,focus:$('nxFocus').value,note:$('nxCheckinNote').value});window.NEXZOShell?.toast?.('Today’s plan context updated.','success');hydrate()};$('nxForgetMistakes').onclick=()=>{window.NEXZOPersonalization.forget('mistakes');hydrate()};$('nxForgetEvents').onclick=()=>{window.NEXZOPersonalization.forget('events');hydrate()};$('nxForgetAll').onclick=()=>{if(confirm('Reset all NEXZO personalization data?')){window.NEXZOPersonalization.forget('all');hydrate()}}}
function init(){window.NEXZOShell?.layout?.('Personalization');bind();hydrate();window.addEventListener('nexzo:personalization-updated',e=>render(e.detail));window.addEventListener('nexzo:personalization-ready',hydrate)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init()})();
